bash -lc cat > /mnt/data/beautify_ppt.py <<'PY'
from pptx import Presentation
from pptx.util import Inches, Pt, Emu
from pptx.dml.color import RGBColor
from pptx.enum.shapes import MSO_SHAPE, MSO_CONNECTOR, MSO_SHAPE_TYPE
from pptx.enum.text import PP_ALIGN, MSO_ANCHOR, MSO_AUTO_SIZE
from pptx.oxml import OxmlElement
from pptx.oxml.ns import qn
from pathlib import Path
from PIL import Image, ImageDraw, ImageFilter
import math, os, shutil

SRC = Path('/mnt/data/数据资产化背景下医疗多源暗数据的激活路径与质量治理研究(1).pptx')
OUT = Path('/mnt/data/数据资产化背景下医疗多源暗数据_美化版.pptx')
ICON_DIR = Path('/mnt/data/ppt_icons_meddata')
ICON_DIR.mkdir(exist_ok=True)

# Theme palette
BG = RGBColor(246, 251, 255)
WHITE = RGBColor(255, 255, 255)
NAVY = RGBColor(18, 48, 79)
DARK = RGBColor(31, 45, 61)
MUTED = RGBColor(91, 111, 130)
BLUE = RGBColor(16, 100, 185)
TEAL = RGBColor(0, 167, 166)
MINT = RGBColor(223, 246, 245)
PALE_BLUE = RGBColor(229, 243, 255)
LINE = RGBColor(197, 224, 238)
LAV = RGBColor(238, 244, 255)
ORANGE = RGBColor(249, 161, 72)
RED = RGBColor(235, 93, 82)
GRAY = RGBColor(145, 160, 175)

FONT = 'Microsoft YaHei'

EMU_PER_INCH = 914400

def inch(x): return Inches(x)

def set_ea_font(run, name=FONT):
    run.font.name = name
    try:
        rPr = run._r.get_or_add_rPr()
        for tag in ('a:latin', 'a:ea', 'a:cs'):
            node = rPr.find(qn(tag))
            if node is None:
                node = OxmlElement(tag)
                rPr.append(node)
            node.set('typeface', name)
    except Exception:
        pass

def apply_text_style(shape, size=14, color=DARK, bold=False, align=None, anchor=None, line_spacing=1.05):
    if not getattr(shape, 'has_text_frame', False):
        return
    tf = shape.text_frame
    tf.word_wrap = True
    if anchor is not None:
        try:
            tf.vertical_anchor = anchor
        except Exception:
            pass
    try:
        tf.auto_size = MSO_AUTO_SIZE.TEXT_TO_FIT_SHAPE
    except Exception:
        pass
    for p in tf.paragraphs:
        if align is not None:
            p.alignment = align
        try:
            p.line_spacing = line_spacing
        except Exception:
            pass
        for run in p.runs:
            set_ea_font(run)
            run.font.size = Pt(size)
            run.font.color.rgb = color
            run.font.bold = bold

def style_paragraph(shape, idx, size=None, color=None, bold=None, align=None):
    if not getattr(shape, 'has_text_frame', False):
        return
    ps = shape.text_frame.paragraphs
    if idx >= len(ps): return
    p = ps[idx]
    if align is not None:
        p.alignment = align
    for run in p.runs:
        set_ea_font(run)
        if size is not None: run.font.size = Pt(size)
        if color is not None: run.font.color.rgb = color
        if bold is not None: run.font.bold = bold

def set_shape_fill(shape, fill_rgb=None, line_rgb=None, line_width=1):
    try:
        if fill_rgb is None:
            shape.fill.background()
        else:
            shape.fill.solid()
            shape.fill.fore_color.rgb = fill_rgb
    except Exception:
        pass
    try:
        if line_rgb is None:
            shape.line.fill.background()
        else:
            shape.line.color.rgb = line_rgb
            shape.line.width = Pt(line_width)
    except Exception:
        pass

def set_line_style(shape, color=TEAL, width=2.0):
    try:
        shape.line.color.rgb = color
        shape.line.width = Pt(width)
    except Exception:
        pass

def move_to_back(shape):
    try:
        spTree = shape._element.getparent()
        spTree.remove(shape._element)
        spTree.insert(2, shape._element)
    except Exception:
        pass

def move_before(shape, ref_shape):
    try:
        spTree = shape._element.getparent()
        spTree.remove(shape._element)
        elems = list(spTree)
        idx = elems.index(ref_shape._element)
        spTree.insert(idx, shape._element)
    except Exception:
        pass

def add_background(slide, prs, slide_idx):
    fill = slide.background.fill
    fill.solid(); fill.fore_color.rgb = BG
    # Full-slide network + soft blobs PNG background
    bg_path = ICON_DIR / f'background_{slide_idx}.png'
    if not bg_path.exists():
        W, H = 1920, 1080
        img = Image.new('RGBA', (W, H), (0,0,0,0))
        d = ImageDraw.Draw(img, 'RGBA')
        # soft blobs drawn on separate layer and blurred
        blobs = Image.new('RGBA', (W,H), (0,0,0,0))
        bd = ImageDraw.Draw(blobs, 'RGBA')
        bd.ellipse((1260,-170,2060,470), fill=(110,210,220,45))
        bd.ellipse((-280,720,460,1460), fill=(70,150,230,35))
        bd.ellipse((1330,780,1780,1230), fill=(140,200,255,28))
        blobs = blobs.filter(ImageFilter.GaussianBlur(22))
        img.alpha_composite(blobs)
        # network nodes upper right
        pts = [(1320,135),(1470,220),(1660,165),(1800,270),(1530,365),(1710,430),(1380,440)]
        for a,b in [(0,1),(1,2),(2,3),(1,4),(4,5),(4,6),(2,5)]:
            d.line([pts[a], pts[b]], fill=(120,190,210,65), width=3)
        for x,y in pts:
            d.ellipse((x-8,y-8,x+8,y+8), fill=(20,160,180,95))
            d.ellipse((x-18,y-18,x+18,y+18), outline=(20,160,180,35), width=2)
        # subtle tiny squares/dots
        for k in range(30):
            x = 90 + (k*137) % 1720
            y = 70 + (k*83) % 920
            if k % 3 == 0:
                d.rounded_rectangle((x,y,x+8,y+8), radius=2, fill=(40,145,190,25))
            else:
                d.ellipse((x,y,x+5,y+5), fill=(40,145,190,20))
        img.save(bg_path)
    pic = slide.shapes.add_picture(str(bg_path), 0, 0, width=prs.slide_width, height=prs.slide_height)
    move_to_back(pic)


def draw_icon(name, path, color=(0,167,166,255), accent=(16,100,185,255), size=512):
    img = Image.new('RGBA', (size,size), (0,0,0,0))
    d = ImageDraw.Draw(img, 'RGBA')
    c = color; a = accent
    lw = 30
    # normalize drawing helpers
    def L(points, fill=c, width=lw, joint='curve'):
        d.line(points, fill=fill, width=width, joint=joint)
    def E(box, outline=c, width=lw):
        d.ellipse(box, outline=outline, width=width)
    def R(box, outline=c, width=lw, radius=50, fill=None):
        d.rounded_rectangle(box, radius=radius, outline=outline, width=width, fill=fill)
    if name == 'database':
        d.ellipse((120,95,392,190), outline=c, width=lw)
        L([(120,140),(120,365)], c, lw)
        L([(392,140),(392,365)], c, lw)
        d.arc((120,318,392,413), 0, 180, fill=c, width=lw)
        d.arc((120,210,392,305), 0, 180, fill=a, width=lw//2)
        d.arc((120,262,392,357), 0, 180, fill=a, width=lw//2)
    elif name == 'heart_pulse':
        # simplified heart plus pulse
        L([(105,270),(175,270),(210,205),(255,340),(300,230),(332,270),(405,270)], a, lw)
        d.arc((105,115,260,280), 200, 350, fill=c, width=lw)
        d.arc((252,115,407,280), 190, 340, fill=c, width=lw)
        L([(122,237),(256,390),(390,237)], c, lw)
    elif name == 'shield_check':
        d.line([(256,70),(395,125),(365,330),(256,440),(147,330),(117,125),(256,70)], fill=c, width=lw, joint='curve')
        L([(185,265),(236,315),(334,205)], a, lw+4)
    elif name == 'network':
        pts=[(120,150),(255,95),(390,160),(180,355),(330,365),(255,250)]
        for i,j in [(0,1),(1,2),(0,5),(2,5),(5,3),(5,4),(3,4)]: L([pts[i],pts[j]], a, 18)
        for p in pts: d.ellipse((p[0]-32,p[1]-32,p[0]+32,p[1]+32), outline=c, width=22, fill=(255,255,255,0))
    elif name == 'watch':
        R((155,125,357,385), outline=c, width=lw, radius=55)
        R((190,55,322,135), outline=a, width=lw, radius=35)
        R((190,377,322,457), outline=a, width=lw, radius=35)
        L([(205,265),(245,265),(265,225),(302,300)], a, lw)
    elif name == 'document':
        d.line([(150,80),(320,80),(390,150),(390,430),(150,430),(150,80)], fill=c, width=lw, joint='curve')
        d.line([(320,80),(320,150),(390,150)], fill=c, width=lw, joint='curve')
        L([(190,225),(320,225)], a, 20)
        L([(190,285),(335,285)], a, 20)
        L([(190,345),(300,345)], a, 20)
    elif name == 'magnify':
        E((120,105,340,325), c, lw)
        L([(300,295),(405,400)], a, lw+2)
    elif name == 'lock':
        R((130,225,382,410), c, lw, radius=35)
        d.arc((170,95,342,275), 180, 360, fill=a, width=lw)
        L([(170,185),(170,235)], a, lw)
        L([(342,185),(342,235)], a, lw)
    elif name == 'ruler':
        d.rounded_rectangle((120,160,392,352), radius=25, outline=c, width=lw)
        for x in [175,225,275,325]:
            L([(x,160),(x,215 if x%100!=25 else 245)], a, 15)
    elif name == 'quality':
        E((105,100,407,402), c, lw)
        L([(175,260),(235,320),(345,205)], a, lw+5)
    elif name == 'loop':
        d.arc((95,125,405,385), 30, 210, fill=c, width=lw)
        d.polygon([(133,324),(88,338),(110,293)], fill=c)
        d.arc((105,125,415,385), 210, 390, fill=a, width=lw)
        d.polygon([(378,186),(424,172),(402,217)], fill=a)
    elif name == 'target':
        for r,wid in [(170,22),(105,22),(42,22)]:
            d.ellipse((256-r,256-r,256+r,256+r), outline=c if r!=105 else a, width=wid)
        L([(256,75),(256,125)], a, 18)
        L([(256,387),(256,437)], a, 18)
        L([(75,256),(125,256)], a, 18)
        L([(387,256),(437,256)], a, 18)
    elif name == 'value':
        d.polygon([(105,205),(205,105),(405,105),(405,305),(305,405),(105,405)], outline=c, fill=None)
        d.line([(105,205),(305,405),(405,305),(405,105),(205,105),(105,205)], fill=c, width=lw, joint='curve')
        E((195,185,255,245), a, 20)
        L([(270,170),(340,170)], a, 18)
        L([(235,295),(340,295)], a, 18)
    elif name == 'gear':
        E((150,150,362,362), c, lw)
        E((215,215,297,297), a, lw)
        for ang in range(0,360,45):
            x1=256+math.cos(math.radians(ang))*125; y1=256+math.sin(math.radians(ang))*125
            x2=256+math.cos(math.radians(ang))*175; y2=256+math.sin(math.radians(ang))*175
            L([(x1,y1),(x2,y2)], c, lw)
    elif name == 'flag':
        L([(150,90),(150,425)], c, lw)
        d.polygon([(165,100),(380,135),(315,225),(165,195)], outline=a, fill=None)
        d.line([(165,100),(380,135),(315,225),(165,195),(165,100)], fill=a, width=lw, joint='curve')
    else:
        E((120,120,392,392), c, lw)
    img.save(path)

icons = ['database','heart_pulse','shield_check','network','watch','document','magnify','lock','ruler','quality','loop','target','value','gear','flag']
for ic in icons:
    p = ICON_DIR / f'{ic}.png'
    if not p.exists():
        draw_icon(ic, p)

def add_icon(slide, name, left, top, size=0.36, circle=True, circle_fill=MINT, circle_line=None):
    if circle:
        circ = slide.shapes.add_shape(MSO_SHAPE.OVAL, inch(left), inch(top), inch(size), inch(size))
        set_shape_fill(circ, circle_fill, circle_line)
    pic = slide.shapes.add_picture(str(ICON_DIR / f'{name}.png'), inch(left+size*0.18), inch(top+size*0.18), width=inch(size*0.64), height=inch(size*0.64))
    return pic

def add_dots(slide, slide_idx):
    # small non-text progress indicator, placed at the upper right under page number
    start_x = 10.05
    y = 0.58
    for i in range(1,8):
        dot = slide.shapes.add_shape(MSO_SHAPE.OVAL, inch(start_x + (i-1)*0.16), inch(y), inch(0.055), inch(0.055))
        set_shape_fill(dot, TEAL if i == slide_idx else LINE, None)


def card(shape, fill=WHITE, line=LINE, line_width=1.0):
    set_shape_fill(shape, fill, line, line_width)
    try:
        shape.text_frame.margin_left = Pt(10)
        shape.text_frame.margin_right = Pt(10)
        shape.text_frame.margin_top = Pt(6)
        shape.text_frame.margin_bottom = Pt(6)
    except Exception:
        pass

def chip(shape, fill=MINT, line=None, text_color=TEAL, size=11, bold=True):
    set_shape_fill(shape, fill, line)
    apply_text_style(shape, size=size, color=text_color, bold=bold, align=PP_ALIGN.CENTER, anchor=MSO_ANCHOR.MIDDLE)


def style_page_number(shape):
    chip(shape, fill=TEAL, line=None, text_color=WHITE, size=10, bold=True)


def fit_picture(pic, x, y, w, h):
    # Preserve image aspect ratio and center it inside box.
    try:
        iw, ih = pic.image.size
        ratio = iw / ih
    except Exception:
        ratio = pic.width / pic.height if pic.height else 1.0
    box_w, box_h = inch(w), inch(h)
    if (box_w / box_h) > ratio:
        new_h = box_h
        new_w = int(box_h * ratio)
    else:
        new_w = box_w
        new_h = int(box_w / ratio)
    pic.left = inch(x) + int((box_w - new_w)/2)
    pic.top = inch(y) + int((box_h - new_h)/2)
    pic.width = int(new_w)
    pic.height = int(new_h)


def frame_existing_picture(slide, pic, x, y, w, h, fill=WHITE, line=LINE):
    fr = slide.shapes.add_shape(MSO_SHAPE.ROUNDED_RECTANGLE, inch(x), inch(y), inch(w), inch(h))
    set_shape_fill(fr, fill, line, 1)
    move_before(fr, pic)
    fit_picture(pic, x+0.12, y+0.12, w-0.24, h-0.24)
    return fr

# Work on a copy of the original so the original content/media remains intact.
shutil.copyfile(SRC, OUT)
prs = Presentation(str(OUT))

for sidx, slide in enumerate(prs.slides, start=1):
    orig_shapes = list(slide.shapes)
    add_background(slide, prs, sidx)
    # Universal formatting
    for sh in orig_shapes:
        if getattr(sh, 'has_text_frame', False):
            apply_text_style(sh, size=12.5, color=DARK, bold=False, align=None, line_spacing=1.1)
        # page number pill
        if getattr(sh, 'has_text_frame', False) and '/ 07' in sh.text:
            style_page_number(sh)
        # Top thin bars
        try:
            if sh.shape_type == MSO_SHAPE_TYPE.AUTO_SHAPE and sh.height < inch(0.25) and sh.width > inch(8):
                set_shape_fill(sh, TEAL, None)
        except Exception:
            pass
    add_dots(slide, sidx)

# Slide-specific layout and styling
# Slide 1
slide = prs.slides[0]
sh = list(slide.shapes)
# original shapes by text/position are still accessible among sh (new background at back, dots at end); use text lookup
orig = [x for x in sh if x.name != 'Picture']
# Main cover card
for x in slide.shapes:
    if getattr(x, 'has_text_frame', False) and '01 / 07' in x.text: x.left, x.top = inch(11.25), inch(0.26)
# Background rounded big shape at index from original: first rounded rect
for x in slide.shapes:
    if x.name == 'Rounded Rectangle 1':
        x.left, x.top, x.width, x.height = inch(0.45), inch(0.54), inch(12.1), inch(6.18)
        set_shape_fill(x, RGBColor(255,255,255), LINE, 1.0)
for x in slide.shapes:
    if getattr(x, 'has_text_frame', False) and x.text.strip() == '课程报告':
        x.left, x.top, x.width, x.height = inch(0.78), inch(0.89), inch(1.1), inch(0.33)
        chip(x, TEAL, None, WHITE, 11, True)
    if getattr(x, 'has_text_frame', False) and '数据资产化背景下医疗多源暗数据' in x.text:
        x.left, x.top, x.width, x.height = inch(0.83), inch(1.35), inch(6.4), inch(1.95)
        apply_text_style(x, size=26, color=NAVY, bold=True, line_spacing=1.0)
        style_paragraph(x, 0, size=29, color=NAVY, bold=True)
        style_paragraph(x, 1, size=29, color=NAVY, bold=True)
        style_paragraph(x, 3, size=16, color=TEAL, bold=True)
    if getattr(x, 'has_text_frame', False) and '课程：数据资产管理' in x.text:
        x.left, x.top, x.width, x.height = inch(0.82), inch(3.75), inch(3.05), inch(0.84)
        apply_text_style(x, size=12.5, color=DARK, bold=False, line_spacing=1.18)
    if x.name == 'Rounded Rectangle 6':
        x.left, x.top, x.width, x.height = inch(0.64), inch(3.55), inch(3.7), inch(1.24)
        set_shape_fill(x, PALE_BLUE, RGBColor(194,222,238), 1)
for label, pos in {'健康数据激活':(2.55,6.02,1.35,0.32),'质量治理':(3.98,6.02,1.12,0.32),'多源':(0.72,4.72,0.86,0.32),'异构':(1.77,4.72,0.86,0.32),'暗数据':(2.82,4.72,0.86,0.32)}.items():
    for x in slide.shapes:
        if getattr(x, 'has_text_frame', False) and x.text.strip()==label:
            x.left, x.top, x.width, x.height = inch(pos[0]), inch(pos[1]), inch(pos[2]), inch(pos[3])
            chip(x, fill=MINT if label in ['健康数据激活','质量治理'] else PALE_BLUE, line=None, text_color=TEAL if label!='质量治理' else BLUE, size=10.5, bold=True)
# frame cover picture
for pic in [x for x in slide.shapes if x.shape_type == MSO_SHAPE_TYPE.PICTURE and 'background_' not in x.name]:
    if pic.left > inch(4):
        frame_existing_picture(slide, pic, 5.25, 2.05, 6.55, 3.85, fill=WHITE, line=LINE)
        break
add_icon(slide, 'heart_pulse', 4.42, 0.95, size=0.62, circle=True, circle_fill=PALE_BLUE)
add_icon(slide, 'database', 4.85, 4.95, size=0.52, circle=True, circle_fill=MINT)
add_icon(slide, 'network', 10.85, 1.20, size=0.50, circle=True, circle_fill=PALE_BLUE)

# Slide 2
slide = prs.slides[1]
for x in slide.shapes:
    if getattr(x, 'has_text_frame', False) and x.text.startswith('背景动机'):
        x.left, x.top, x.width, x.height = inch(0.55), inch(0.25), inch(7.0), inch(0.75)
        apply_text_style(x, 15, TEAL, True)
        style_paragraph(x, 1, size=24, color=NAVY, bold=True)
    if getattr(x, 'has_text_frame', False) and '02 / 07' in x.text:
        x.left, x.top = inch(11.35), inch(0.25)
    if x.name == 'Rounded Rectangle 4':
        x.left, x.top, x.width, x.height = inch(0.55), inch(1.35), inch(4.55), inch(3.8)
        card(x)
    if getattr(x, 'has_text_frame', False) and '年轻人会持续产生' in x.text:
        x.left, x.top, x.width, x.height = inch(0.84), inch(1.74), inch(4.0), inch(2.75)
        apply_text_style(x, 15.2, DARK, False, line_spacing=1.16)
    if x.name == 'Rounded Rectangle 6':
        x.left, x.top, x.width, x.height = inch(5.45), inch(1.04), inch(6.85), inch(5.15)
        card(x)
# picture
for pic in [p for p in slide.shapes if p.shape_type == MSO_SHAPE_TYPE.PICTURE and 'background_' not in p.name]:
    fit_picture(pic, 5.70, 1.30, 6.35, 4.40)
# chips
for label, style in {'数据不少':(6.15,6.02,1.02,0.32,PALE_BLUE,BLUE),'但未入治理':(7.25,6.02,1.38,0.32,LAV,BLUE),'进入受控流程':(9.72,6.00,1.65,0.36,MINT,TEAL)}.items():
    for x in slide.shapes:
        if getattr(x, 'has_text_frame', False) and x.text.strip()==label:
            x.left,x.top,x.width,x.height=inch(style[0]),inch(style[1]),inch(style[2]),inch(style[3])
            chip(x, style[4], None, style[5], 10.5, True)
# empty arrow-ish rounded rectangle from original
for x in slide.shapes:
    if x.name == 'Rounded Rectangle 10':
        x.left,x.top,x.width,x.height=inch(9.20),inch(6.04),inch(0.36),inch(0.22)
        set_shape_fill(x, TEAL, None)
add_icon(slide,'database',0.86,4.62,size=0.42,circle=True,circle_fill=MINT)
add_icon(slide,'network',1.45,4.62,size=0.42,circle=True,circle_fill=PALE_BLUE)
add_icon(slide,'shield_check',2.04,4.62,size=0.42,circle=True,circle_fill=MINT)

# Slide 3
slide = prs.slides[2]
for x in slide.shapes:
    if getattr(x,'has_text_frame',False) and x.text.startswith('真实场景证据'):
        x.left,x.top,x.width,x.height=inch(0.55),inch(0.25),inch(7.2),inch(0.75)
        apply_text_style(x,15,TEAL,True)
        style_paragraph(x,1,24,NAVY,True)
    if getattr(x,'has_text_frame',False) and '03 / 07' in x.text: x.left,x.top=inch(11.35),inch(0.25)
    if x.name == 'Rounded Rectangle 4':
        x.left,x.top,x.width,x.height=inch(0.55),inch(1.32),inch(5.85),inch(4.95)
        card(x)
    if x.name == 'Rounded Rectangle 5':
        x.left,x.top,x.width,x.height=inch(6.55),inch(1.32),inch(5.85),inch(4.95)
