    img = Image.new('"'"'RGBA'"'"', (size,size), (0,0,0,0))
    d = ImageDraw.Draw(img, '"'"'RGBA'"'"')
    c = color; a = accent
    lw = 30
    # normalize drawing helpers
    def L(points, fill=c, width=lw, joint='"'"'curve'"'"'):
        d.line(points, fill=fill, width=width, joint=joint)
    def E(box, outline=c, width=lw):
        d.ellipse(box, outline=outline, width=width)
    def R(box, outline=c, width=lw, radius=50, fill=None):
        d.rounded_rectangle(box, radius=radius, outline=outline, width=width, fill=fill)
    if name == '"'"'database'"'"':
        d.ellipse((120,95,392,190), outline=c, width=lw)
        L([(120,140),(120,365)], c, lw)
        L([(392,140),(392,365)], c, lw)
        d.arc((120,318,392,413), 0, 180, fill=c, width=lw)
        d.arc((120,210,392,305), 0, 180, fill=a, width=lw//2)
        d.arc((120,262,392,357), 0, 180, fill=a, width=lw//2)
