def add_icon(slide, name, left, top, size=0.36, circle=True, circle_fill=MINT, circle_line=None):
    if circle:
        circ = slide.shapes.add_shape(MSO_SHAPE.OVAL, inch(left), inch(top), inch(size), inch(size))
