    return pic

def add_dots(slide, slide_idx):
    # small non-text progress indicator, placed at the upper right under page number
    start_x = 10.05
    y = 0.58
    for i in range(1,8):
        dot = slide.shapes.add_shape(MSO_SHAPE.OVAL, inch(start_x + (i-1)*0.16), inch(y), inch(0.055), inch(0.055))
        set_shape_fill(dot, TEAL if i == slide_idx else LINE, None)


def card(shape, fill=WHITE, line=LINE, line_width=1.0):
    set_shape_fill(shape, fill, line, line_width)
    try:
        shape.text_frame.margin_left = Pt(10)
        shape.text_frame.margin_right = Pt(10)
        shape.text_frame.margin_top = Pt(6)
        shape.text_frame.margin_bottom = Pt(6)
    except Exception:
        pass

def chip(shape, fill=MINT, line=None, text_color=TEAL, size=11, bold=True):
    set_shape_fill(shape, fill, line)
    apply_text_style(shape, size=size, color=text_color, bold=bold, align=PP_ALIGN.CENTER, anchor=MSO_ANCHOR.MIDDLE)


def style_page_number(shape):
    chip(shape, fill=TEAL, line=None, text_color=WHITE, size=10, bold=True)


def fit_picture(pic, x, y, w, h):
    # Preserve image aspect ratio and center it inside box.
    try:
        iw, ih = pic.image.size
        ratio = iw / ih
    except Exception:
        ratio = pic.width / pic.height if pic.height else 1.0
    box_w, box_h = inch(w), inch(h)
    if (box_w / box_h) > ratio:
        new_h = box_h
        new_w = int(box_h * ratio)
    else:
        new_w = box_w
        new_h = int(box_w / ratio)
    pic.left = inch(x) + int((box_w - new_w)/2)
    pic.top = inch(y) + int((box_h - new_h)/2)
    pic.width = int(new_w)
    pic.height = int(new_h)


def frame_existing_picture(slide, pic, x, y, w, h, fill=WHITE, line=LINE):
    fr = slide.shapes.add_shape(MSO_SHAPE.ROUNDED_RECTANGLE, inch(x), inch(y), inch(w), inch(h))
    set_shape_fill(fr, fill, line, 1)
    move_before(fr, pic)
    fit_picture(pic, x+0.12, y+0.12, w-0.24, h-0.24)
    return fr

